let activeIndex = 0;

<div>
  <div role="tablist">
    <for|tab, i| of=input.tab>
      <button
        aria-selected=(i === activeIndex ? "true" : undefined)
        on-click() {
          activeIndex = i;
        }
      >
        ${tab.label}
      </button>
    </for>
  </div>

  <div id="panel">
    ${input.tab[activeIndex]?.renderBody()}
  </div>

  <@slot name="tab" label />
</div>

import { getProduct } from "../../../catalog.js";

export const params = {
  id: String,
};

export async function getData({ params }) {
  return {
    product: getProduct(params.id),
  };
}

